Question: Implement a stack using an array.

Answer:
```csharp
class Stack
{
    private int[] arr;
    private int top;

    public Stack()
    {
        arr = new int[100];
        top = -1;
    }

    public void NAME_1(int item)
    {
        if (top == arr.Length)
        {
            arr = Array.Resize(arr, arr.Length * 2);
        }
        arr[++top] = item;
    }

    public int Pop()
    {
        if (top < 0)
        {
            throw new InvalidOperationException("Stack is empty.");
        }
        int item = arr[top--];
        return item;
    }

    public int NAME_2()
    {
        if (top < 0)
        {
            throw new InvalidOperationException("Stack is empty.");
        }
        return arr[top];
