int min_calculations(int n) {
    int num = n;
    int min_calculations = 1;

    while (num != 0) {
        int div = 0;
        while (num >= 3 * div) {
            div++;
            num /= 3;
        }

        if (num >= 2 * div) {
            div++;
            num /= 2;
        }

        num -= div * (num / div);
        min_calculations++;

        if (num == 0) {
            break;
        }
    }

    return min_calculations;
}

