```less
func quickSort<T: Comparable>(array: [T], left: Int, right: Int) -> [T] {
    if left < right {
        let pivot = array[(left + right) // 2]
        let i = partition(array, left: left, right: right, pivot: pivot)

        return quickSort(array: array, left: left, right: i - 1)
    } else {
        return array
    }
}

func partition<T: Comparable>(array: [T], left: Int, right: Int, pivot: T) -> Int {
    var i = left - 1
    var j = right
    while i <= j {
        while array[i] < pivot && i < j {
            i += 1
        }
        while array[j] > pivot && j > i {
            j -= 1
        }
        if i <= j {
            swap(&array[i], &array[j])
            i += 1
            j -= 1
        }
    }
    swap(&array[i], &array[j])
    return i
}

func swap<T>(inout first: T, second: T) {
    let temp = first
    first = second
    second = temp
}
```
This implementation takes an array of comparable elements, and two indices representing the left and right ends of the sub-array to be sorted. It uses the pivot element method to choose a pivot element and partition the sub-array into two parts, one with elements less than the pivot and the other with elements greater than the pivot. It then recursively sorts the sub-arrays on either side of the pivot until the entire array is sorted.

