using System.IO;
using UnityEngine;

public class SettingsMenu : MonoBehaviour
{
    public string settingName;
    public string settingValue;

    void Start()
    {
        // Check if the settings file exists
        string saveFolder = Application.persistentDataPath + "/Settings/";
        if (!Directory.Exists(saveFolder))
        {
            Directory.CreateDirectory(saveFolder);
        }

        string settingsFile = saveFolder + settingName + ".txt";
        if (File.Exists(settingsFile))
        {
            // Read the settings from the file
            string fileContents = File.ReadAllText(settingsFile);
            settingValue = fileContents;

            // Load the settings from the file
            LoadSettings();
        }
        else
        {
            // Save the settings to the file
            SaveSettings();
        }
    }

    void LoadSettings()
    {
        // Load the saved settings from the file
        string saveFolder = Application.persistentDataPath + "/Settings/";
        string settingsFile = saveFolder + settingName + ".txt";
        if (File.Exists(settingsFile))
        {
            // Load the settings from the file
            string fileContents = File.ReadAllText(settingsFile);
            settingValue = fileContents;
        }
    }

    void SaveSettings()
    {
        // Save the current settings to the file
        string saveFolder = Application.persistentDataPath + "/Settings/";
        string settingsFile = saveFolder + settingName + ".txt";

        // Create the file if it doesn't exist
        if (!File.Exists(settingsFile))
        {
            File.Create(settingsFile).Close();
        }

        // Write the settings to the file
        string fileContents = settingName + " = " + settingValue + "\n";
        File.WriteAllText(settingsFile, fileContents);
    }
}
