```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAXN 1000000

int n;
struct timespec ts_begin, ts_end;
double elapsed;

void init() {
    n = 0;
    ts_begin = ts_end = time(NULL);
}

void sort(int *a, int n, int left, int right) {
    if (left < n && right < n) {
        int mid = (left + right) / 2;
        sort(a, n, left, mid);
        sort(a, n, mid + 1, right);
    }
}

void merge(int *a1, int *a2, int n, int left, int right) {
    if (left < n && right < n) {
        int mid = (left + right) / 2;
        int i = left, j = right;
        while (i <= mid && j <= mid) {
            if (a1[i] <= a2[j]) {
                a[i + 1] = a1[i];
            } else {
                a[j + 1] = a2[j];
            }
            i++;
            j++;
        }
        if (i <= right) {
            a[i + 1] = a1[i];
        } else {
            a[j + 1] = a2[j];
        }
    }
}

int main() {
