const bip39 = require('bip39');

// Generate a seed phrase
const seedPhrase = bip39.bip39(
  "english", // Language of the seed phrase
  "TESTCHAIN", // Purpose of the seed phrase (optional)
  null, // Entropy (optional)
  10 // Number of words in the seed phrase
);

console.log("Seed phrase: " + seedPhrase);

// Derive private keys and public keys from the seed phrase
const mnemonic = bip39.mnemonic(seedPhrase);
const masterPrivateKey = bip39.hdmaster(mnemonic);

for (let i = 0; i < 10; i++) {
  const privateKey = bip39.privkey(masterPrivateKey, i);
  const publicKey = bip39.pubkey(privateKey);
  console.log(`Private key #${i + 1}: ${privateKey}`);
