```c
#include <stdio.h>

void multiply_matrices(int a[][3], int b[][3], int result[][3], int row_a, int col_a, int row_b, int col_b) {
    if (col_a != row_b) {
        printf("Matrix multiplication not possible due to incompatible dimensions.\n");
        return;
    }

    for (int i = 0; i < row_a; i++) {
        for (int j = 0; j < col_b; j++) {
            result[i][j] = 0;
            for (int k = 0; k < col_a; k++) {
                result[i][j] += a[i][k] * b[k][j];
            }
        }
    }
}

int main() {
    int a[2][3] = {
        {1, 2, 3},
        {4, 5, 6},
    };

    int b[3][3] = {
        {7, 8, 9},
        {10, 11, 12},
        {13, 14, 15},
    };

    int row_a = sizeof(a) / sizeof(a[0]);
    int col_a = sizeof(a[0]) / sizeof(a[0][0]);
    int row_b = sizeof(b) / sizeof(b[0]);
    int col_b = sizeof(b[0]) / sizeof(b[0][0]);

    int result[2][3];

    multiply_matrices(a, b, result, row_a, col_a, row_b, col_b);

    // Print the result matrix
    for (int i = 0; i < row_a; i++) {
        for (int j = 0; j < col_b; j++) {
            printf("%d ", result[i][j]);
        }
        printf("\n");
    }

    return 0;
}
```

