```rust
use std::env;
use std::fs::File;
use std::io::{Seek, Write};
use std::process::{Command, Stdio};
fn execute_binary(binary: &str) {
    let mut file = File::open(binary).unwrap();
    let mut binary_contents = vec![0; file.seek(SeekFrom::End(0)).unwrap() as usize];
    file.read_to_end(&mut binary_contents).unwrap();
    let mut command = Command::new("./".into());
    command.stdin(Stdio::piped());
    let process = command.spawn().unwrap();
    let mut stdout = process.stdout.unwrap();
    stdout.write_all(&binary_contents).unwrap();
    process.wait().unwrap();
}
fn main() {
    let binary = "path/to/binary";
    execute_binary(binary);
}
```
