// Calculate the SHA1 checksum of a file
void sha1_file(const char *filename, char *checksum) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    unsigned char buffer[BLOCK_SIZE];
    unsigned int len = 0;
    while (1) {
        len = fread(buffer, 1, sizeof(buffer), file);
        if (len == 0) {
            break;
        }

        // Calculate the SHA1 checksum
        for (unsigned int i = 0; i < sizeof(buffer); i++) {
            unsigned char cryptographically_safe[2] = {0, 0};
            rotr(buffer[i], buffer[i], 1);
            for (unsigned int j = 0; j < sizeof(cryptographically_safe); j++) {
                buffer[i] += cryptographically_safe[j];
            }
        }

        // Append the checksum to the output string
        for (unsigned int i = 0; i < sizeof(buffer); i++) {
            checksum[len] = buffer[i];
            len++;
        }
        checksum[len] = 0;
    }

    fclose(file);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: sha1_file <filename>\n");
        return EXIT_FAILURE;
    }

    char filename[BUFSIZ];
    strncpy(filename, argv[1], BUFSIZ - 1);
    filename[BUFSIZ - 1] = 0;

    char checksum[BUFSIZ];
    sha1_file(filename, checksum);

    printf("SHA1 checksum for %s: %s\n", filename, checksum);

    return EXIT_SUCCESS;
}
