```sql
CREATE OR REPLACE FUNCTION fibonacci(n IN NUMBER)
  RETURN NUMBER IS
  a NUMBER := 0;
  b NUMBER := 1;
  res NUMBER;
  -- check if n is zero
  IF n = 0 THEN
    RETURN b;
  ELSE
    -- calculate the nth Fibonacci number
    res := a + b;
    a := b;
    b := res;
    RETURN res;
  END IF;
END;
```
