    T variance(size_t i, size_t j) const {
        T sum = 0;
        if (i == j) {
            sum = diagonal_[i];
        } else {
            sum = (diagonal_[i] + diagonal_[j]) / 2;
        }
        return sum - (mean(i, j) * mean(i, j));
    }

    T covariance(size_t i, size_t j) const {
        T sum = 0;
        if (i == j) {
            sum = diagonal_[i];
        } else {
            sum = (diagonal_[i] + diagonal_[j]) / 2;
        }
        return sum - (mean(i, j) * mean(i, j));
    }

private:
    size_t m_;
    size_t n_;
    std::array<T, 2> diagonal_;
    std::vector<std::array<T, 2>> off_diagonal_;
};
