Here is a C++ winapi application that will track global window events and set window position and size randomly on the window show event:

```cpp
#include <windows.h>
#include <iostream>

LRESULT CALLBACK window_hook(HWND hwnd, UINT message, WPARAM wparam, LPARAM lparam)
{
    switch (message)
    {
        case WM_SHOWWINDOW:
            {
                // Randomly set window position and size
                int width = rand() % 800;
                int height = rand() % 600;
                SetWindowPos(hwnd, NULL, width / 2 - 50, height / 2 - 50, 0, 0, SWP_NOZORDER);
                SetWindowSize(hwnd, width, height);

                // Store window position and size for tracking
                std::cout << "Window position: (" << width << ", " << height << ")";

                return 0;
            }
    }

    return DefWindowProc(hwnd, message, wparam, lparam);
}

int main()
{
    // Create a new window
    HWND hwnd = CreateWindowA("GlobalWindow", "Global window", WS_OVERLAPPEDWINDOW, 100, 100, 300, 300, NULL, NULL, GetModuleHandle(NULL), NULL);

    // Register the window hook
    SetWindowEvent(hwnd, WM_SHOWWINDOW, window_hook, NULL);

    // Run the application
    while (true)
    {
        Sleep(1000);
    }

    return 0;
}
```

This code creates a new window and then registers a window hook that is called when the window is shown. The window hook randomly sets the window position and size, stores the position and size for tracking, and then calls the DefWindowProcedure to ensure that the window is displayed correctly. The while (true) loop in the main function continuously sleeps for 1000 milliseconds, allowing the application to run continuously.

