Here is an example implementation of a VSCode extension that replaces all `<el-input>` tags with `<input>` tags in the currently open file:

```javascript
const vscode = require('vscode');

function activate(context) {
    console.log('Extension activated!');

    let disposable = vscode.commands.registerCommand('extension.replaceElInput', function () {
        // Get the active editor
        let editor = vscode.window.activeTextEditor;
        if (!editor) {
            return; // No open text editor
        }

        // Get the document and its text content
        let document = editor.document;
        let text = document.getText();

        // Replace all <el-input> tags with <input> tags
        let newText = text.replace(/<el-input/g, '<input');

        // Update the editor with the new text content
        let edit = new vscode.WorkspaceEdit();
        edit.replace(document.uri, new vscode.Range(0, 0, document.lineCount, 0), newText);
        vscode.workspace.applyEdit(edit);
    });

    context.subscriptions.push(disposable);
}

function deactivate() {
    console.log('Extension deactivated!');
}

module.exports = {
    activate,
    deactivate
};
```

To use this extension, you can save the above code into a `extension.js` file and create a `package.json` file with the following contents:

```json
{
    "name": "replace-el-input",
    "displayName": "Replace el-input with input",
    "description": "Replaces all <el-input> tags with <input> tags.",
    "version": "1.0.0",
    "publisher": "YourName",
    "engines": {
        "vscode": "^1.0.0"
    },
    "categories": [
        "Other"
    ],
    "activationEvents": [
        "onCommand:extension.replaceElInput"
    ],
    "main": "./extension.js",
    "contributes": {
        "commands": [
            {
                "command": "extension.replaceElInput",
                "title": "Replace el-input with input"
            }
        ]
    }
}
```

Then, in VSCode, go to the Extensions panel, click the "..." icon, and select "Install from VSIX". Choose the folder where the `package.json` and `extension.js` files are located, and the extension will be installed. You can then use the command palette (Ctrl+Shift+P) to run the "Replace el-input with input" command.

