#define JDY41_SERVICE_UUID    "0000ffe0-0000-1000-8000-00805f9b34fb"
#define JDY41_CHAR_UUID      "0000ffe1-0000-1000-8000-00805f9b34fb"

// Connect to JDY41 module 
int jdy41_connect(char *address) {
    // Create Bluetooth socket
    int sock = socket(AF_BLUETOOTH, SOCK_STREAM, BTPROTO_RFCOMM);

    // Connect to JDY41 module
    struct sockaddr_rc addr;
    memset(&addr, 0, sizeof(addr));
    addr.rc_family = AF_BLUETOOTH;
    addr.rc_channel = 1;
    str2ba(address, &addr.rc_bdaddr);
    int status = connect(sock, (struct sockaddr *)&addr, sizeof(addr));
    if (status != 0) {
        perror("Failed to connect");
        return -1; 
    }

    return sock;
}

// Disconnect from JDY41 module
void jdy41_disconnect(int sock) {
    close(sock);
}

// Send data to JDY41 module 
int jdy41_send(int sock, char *data, int length) {
    int status = send(sock, data, length, 0);
    if (status != length) {
        perror("Failed to send data");
        return -1; 
    }
    return 0;
}

// Receive data from JDY41 module
int jdy41_receive(int sock, char *buffer, int length) {
    int received = 0;
    while (received < length) {
        int n = recv(sock, buffer + received, length - received, 0);
        if (n <= 0) break;
        received += n;
    }
    return received; 
}

