fn unwrap_transaction(transaction: &Transaction) -> (i32, Vec<Input>, Vec<Output>, u32) {
    let (version, inputs, outputs, locktime) = (
        transaction.version,
        transaction.inputs.into_iter().map(|input| input.clone()).collect(),
