void quicksort(int a[], int l, int r) {
    int i = l - 1, j = r, k, p = l - 1, q = r, v = a[r];
    if (r <= l) return;
    for (;;) {
        while (a[++i] < v) ;
        while (v < a[--j]) if (j == l) break;
        if (i >= j) break;
        exchange(a[i], a[j]);
        if (a[i] == v) { p++; exchange(a[p], a[i]); }
        if (v == a[j]) { q--; exchange(a[j], a[q]); }
    }
    exchange(a[i], a[r]);
    j = i - 1;
    i = i + 1;
    for (k = l; k < p; k++, j--)
        exchange(a[k], a[j]);
    for (k = r - 1; k > q; k--, i++)
        exchange(a[i], a[k]);
    quicksort(a, l, j);
    quicksort(a, i, r);
}
```

