```csharp
using System;
using System.IO;
using System.IO.Compression;

class ZipFileParser
{
    static void Main(string[] args)
    {
        // The path to the zip file
        string zipFilePath = @"C:\example.zip";

        // Open the zip file
        using (ZipArchive archive = ZipFile.OpenRead(zipFilePath))
        {
            // Get the entries in the archive
            foreach (ZipArchiveEntry entry in archive.Entries)
            {
                // Check if the entry is a directory
                if (entry.IsDirectory)
                {
                    // Print the name of the directory
                    Console.WriteLine(entry.Name);

                    // Recursively parse the directory's contents
                    ParseDirectoryContents(entry);
                }
                else
                {
                    // Print the name of the file
                    Console.WriteLine(entry.Name);
                }
            }
        }
    }

    static void ParseDirectoryContents(ZipArchiveEntry entry)
    {
        // Check if the entry is a directory
        if (entry.IsDirectory)
        {
            // Get the entries in the directory
            foreach (ZipArchiveEntry subEntry in entry.Entries)
            {
                // Check if the entry is a directory
                if (subEntry.IsDirectory)
                {
                    // Recursively parse the subdirectory's contents
                    ParseDirectoryContents(subEntry);
                }
                else
                {
                    // Print the name of the file
                    Console.WriteLine(subEntry.Name);
                }
            }
        }
    }
}
```
