let x = 0;
let y = 0;
let angle = 360 / 5;
let polygon = [];

function setup() {
  createCanvas(500, 500);
  polygon = [];
  for (let i = 0; i < 5; i++) {
    let point = rotate(x, y, angle);
    polygon.push(point);
    x += 10;
    y += 10;
  }
}

function draw() {
  background(255);
  stroke(0);
  noFill();
  for (let i = 0; i < polygon.length; i++) {
    let point = polygon[i];
    vertex(point.x, point.y);
    angle -= 360 / 5;
  }
  vertex(polygon[0].x, polygon[0].y);
}

function rotate(x, y, angle) {
  let cos = Math.cos(angle);
  let sin = Math.sin(angle);
  return {
    x: x * cos - y * sin,
    y: x * sin + y * cos,
  };
}
