function endsWith(str, suffix) {
  // Get the length of the string and the suffix
  var strLen = str.length;
  var suffixLen = suffix.length;

  // Check if the string is longer than the suffix
  if (strLen > suffixLen) {
    return false;
  }

  // Check if the string starts with the suffix
  return str.indexOf(suffix) === strLen - suffixLen;
}

