```go
package main

import (
    "fmt"
    "sort"
)

func inPlaceBubbleSort(arr []int) {
    n := len(arr)
    for i := 0; i < n-1; i++ {
        for j := 0; j < n-i-1; j++ {
            if arr[j] > arr[j+1] {
                arr[j], arr[j+1] = arr[j+1], arr[j]
            }
        }
    }
}

func main() {
    arr := []int{3, 4, 1, 5, 2}
    fmt.Println(arr)
    inPlaceBubbleSort(arr)
    fmt.Println(arr)
}
```
This implementation uses two nested loops to iterate over the elements of the array and compare adjacent elements. If an element is greater than the next element, it swaps them. The algorithm continues until the array is sorted in place.

