Here is a basic card game in C++ that uses nine moveable cards from 1 through 9:
```c
#include <iostream>
using namespace std;

const int NUM_CARDS = 9;
const int CARDS_PER_ROUND = 4;
int deck[NUM_CARDS] = {1, 2, 3, 4, 5, 6, 7, 8, 9};
int round_winners[NUM_CARDS][CARDS_PER_ROUND];

// Function to deal cards to a player
void deal_cards(int player) {
    int cards_dealt[CARDS_PER_ROUND];
    int i;
    for (i = 0; i < CARDS_PER_ROUND; i++) {
        cards_dealt[i] = deck[player * CARDS_PER_ROUND + i];
    }
    round_winners[player][0] = cards_dealt[0];
}

// Function to determine the winner of a round
int determine_winner(int round_num, int player_1, int player_2) {
    int i;
    for (i = 0; i < CARDS_PER_ROUND; i++) {
        if (round_winners[player_1][i] > round_winners[player_2][i]) {
            return player_1;
        } else if (round_winners[player_1][i] < round_winners[player_2][i]) {
            return player_2;
        }
    }
    return 0;
}

int main() {
    int player_1 = 0;
    int player_2 = 1;
    int round_num = 0;

    while (player_1 != player_2) {
        deal_cards(player_1);
        deal_cards(player_2);
        round_num++;
        if (round_num > 4) {
            cout << "Player 1 wins!" << endl;
            return 0;
        }
        int winner = determine_winner(round_num, player_1, player_2);
        if (winner == player_1) {
            cout << "Player 1 wins!" << endl;
        } else if (winner == player_2) {
            cout << "Player 2 wins!" << endl;
        } else {
            cout << "It's a tie!" << endl;
        }
        round_winners[player_1][round_num - 1] = round_winners[player_2][round_num - 1];
        round_winners[player_2][round_num - 1] = 0;
    }
    cout << "It's a tie!" << endl;
    return 0;
}
```
This code creates a deck of nine cards from 1 to 9 and uses two players, each taking turns to pick up cards until one player has won four rounds. The `determine_winner` function compares the values of the cards in each round to determine the winner. The `round_winners` array keeps track of which cards have been picked up in each round, and is used to determine if a player has won a round.

