function handleKeyDown(event) {
  switch (event.key) {
    case 'a':
      direction = 'up';
      break;
    case 'd':
      direction = 'down';
      break;
    case 'w':
      direction = 'left';
      break;
    case 's':
      direction = 'right';
      break;
    default:
      break;
  }
}

function move() {
  let newSnake = [...snake];
  newSnake[head][0] = direction;
  newSnake[tail][0] = direction;
  newSnake[head][1] = direction;
  newSnake[tail][1] = direction;
  newSnake[head][2] = direction;
  newSnake[tail][2] = direction;
  head++;
  tail++;
  if (head >= width || tail >= height) {
    head = 0;
    tail = width * height;
  }
  snake = newSnake;
  head = 0;
  tail = width * height;
}

