  for (let i = 0; i < snake.length; i++) {
    for (let j = 0; j < snake[i].length; j++) {
      let direction = snake[i][j][0];
      let newX = i * width;
      let newY = j * height;
      switch (direction) {
        case 'up':
          newY -= direction;
          break;
        case 'down':
          newY += direction;
          break;
        case 'left':
          newX -= direction;
          break;
