In Rust, you can convert a reference to a `Value` into a type implementing `Deserialize` without cloning by using a borrowed reference. The main challenge here is that `From` is not implemented for `&Value`. However, you can create an adapter struct that implements `From<Value>` by borrowing the inner value and then implements `Deserialize`.

Here's an example:
```rust
use serde::{Deserialize, Serialize};
use serde_json::json;

#[derive(Debug, PartialEq, Serialize, Deserialize)]
pub enum Value {
    Number(f64),
    String(String),
    Boolean(bool),
    Null,
    Array(Vec<Value>),
    Object({
        let mut obj = BTreeMap::new();
        for (key, value) in iter.into_iter() {
            obj.insert(key, value);
        }
        obj
    }),
}

pub struct Adapt<T: Deserialize> {
    value: Value,
}

impl<T: Deserialize> Adapt<T> {
    pub fn new(value: Value) -> Self {
        Adapt { value: value }
    }
}

impl From<Value> for Adapt<T> {
    fn from(value: Value) -> Self {
        Adapt { value: value }
    }
}

impl<T: Deserialize> Deserialize for Adapt<T> {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let value = Value::from(deserializer.deserialize_any)?;
        Ok(Self::new(value))
    }
}

fn main() {
    let json = r#"{
        "name": "NAME_1",
        "age": 30,
        "is_student": false
    }"#;

    let result: Vec<Adapt<serde_json::Value>> = serde_json::from_str(json).unwrap();
}
```
