Here's a Unity editor script that converts the format of a texture to GraphicsFormat.R32G32B32A32\_SFloat:
```csharp
using UnityEngine;
using UnityEditor;

public class ConvertTextureFormat : MonoBehaviour
{
    [MenuItem("Tools/Convert Texture Format")]
    static void ConvertTexture()
    {
        Texture2D texture = Selection.activeTexture;
        if (texture != null)
        {
            int width = texture.width;
            int height = texture.height;
            int[] pixels = new int[width * height];
            texture.GetPixels(pixels, 0, width, 0, 0, width, height);

            // Convert the texture to R32G32B32A32_SFloat format
            for (int i = 0; i < pixels.Length; i++)
            {
                pixels[i] = (((float)pixels[i] / 255.0f) * 0.5f) * 255.0f;
            }

            // Create a new texture with the converted format
            Texture2D convertedTexture = new Texture2D(width, height, TextureFormat.R32G32B32A32_SFloat, false);
            convertedTexture.SetPixels(pixels, 0, width, 0, 0, width, height);

            // Save the converted texture
            SaveTexture(convertedTexture);

            // Delete the original texture
            Destroy(texture);
        }
    }

    private static void SaveTexture(Texture2D texture)
    {
        // Save the texture to a file
        string path = Application.dataPath + "/Textures/";
        path += texture.name;
        texture.SaveAs(path, TextureFormat.PNG);
    }
}
```
