	if err != nil {
		panic(err)
	}
	defer file.Close()

	// Create a new multipart form body
	body := &bytes.Buffer{}
	writer := multipart.NewWriter(body)

	// Add the file to the form body
	part, err := writer.CreateFormFile("file", "file.txt")
	if err != nil {
		panic(err)
	}
	_, err = io.Copy(part, file)
	if err != nil {
		panic(err)
	}
	part.Close()

	// Set any additional form fields
	// ...

	// Upload the file to the server
	req, err := http.NewRequest(http.MethodPost, "http://example.com/upload", body)
	if err != nil {
		panic(err)
	}

	// Set any additional request headers
	// ...

	client := httpx.NewClient()
	resp, err := client.Do(req)
	if err != nil {
		panic(err)
