function splitCodeBlock(codeBlock) {
  const result = [];
  let startIndex = 0;
  let endIndex = 0;
  let insideCodeBlock = false;
  for (let i = 0; i < codeBlock.length; i++) {
    if (codeBlock[i] === '`') {
      if (!insideCodeBlock) {
        startIndex = i;
        insideCodeBlock = true;
      } else {
        endIndex = i;
        result.push(codeBlock.substring(startIndex, endIndex));
        startIndex = i + 1;
        insideCodeBlock = false;
      }
    } else if (codeBlock[i] === '"') {
      if (!insideCodeBlock) {
        startIndex = i;
        insideCodeBlock = true;
      }
    }
  }
