Here's a short Go program for an HTTP client that supports mutual TLS with self-signed certificates:
```go
package main

import (
    "crypto/tls"
    "crypto/x509"
    "fmt"
    "io/ioutil"
    "log"
    "net/http"
)

func main() {
    // Read client cert and key from files
    clientCert, err := ioutil.ReadFile("client.cert")
    if err != nil {
        log.Fatal(err)
    }    
    clientKey, err := ioutil.ReadFile("client.key")
    if err != nil {
        log.Fatal(err)
    }

    // Read CA cert for server 
    caCert, err := ioutil.ReadFile("ca.cert")
    if err != nil {
        log.Fatal(err)
    }

    // Create TLS config
    tlsConfig := &tls.Config {
        Certificates: []tls.Certificate{tls.Certificate{Certificates: [][]byte{clientCert}, PrivateKey: []byte(clientKey)}},
        RootCAs:      x509.NewCertPool(),
    }
    tlsConfig.RootCAs.AppendCertsFromPEM(caCert)

    // Create HTTP client with TLS config
    client := &http.Client{
        Transport: &http.Transport{
            TLSClientConfig: tlsConfig,
        },
    }

    // Make request
    resp, err := client.Get("https://example.com")
    if err != nil {
        log.Fatal(err)
    }

    fmt.Println(resp.Status)
}
```

This program reads the client certificate, key and CA certificate from files, configures a TLS client config for mutual TLS, creates an HTTP client with that config, and makes a request to an example HTTPS URL.

