```swift
import Foundation

func loadJSON<T>(_ type: T.Type, _ key: String) -> [T] {
    let bundle = Bundle(for: JSONLoader.self)
    guard let url = bundle.url(forResource: key, withExtension: "json") else {
        return []
    }

    do {
        let data = try Data(contentsOf: url)
        return try JSONDecoder().decode([T].self, from: data)
    } catch {
        print("Failed to load JSON: \(error.localizedDescription)")
        return []
    }
}
```
