public static int CalculateLevelConfiguration(int currentLevel)
{
    int levelCount = 350;
    int cycleBucket = 350;
    int cycleStart = 100;
    int cycleEnd = 350;

    if (currentLevel <= cycleStart)
    {
        return cycleStart;
    }
    else if (currentLevel >= cycleEnd)
    {
        return cycleEnd;
    }
    else
    {
        int index = (currentLevel - cycleStart) / (cycleEnd - cycleStart);
        int remainder = currentLevel - (index * (cycleEnd - cycleStart));
        int configIndex = remainder % levelCount;
        return configIndex + cycleStart;
    }
}
