int findMedian(int arr[], int n) {
    // Sort the array
    qsort(arr, n, sizeof(int), compare);

    // Check if n is even or odd
    if (n % 2 == 0) {
        // If n is even, return average of middle two elements
        return (arr[n/2] + arr[n/2 - 1]) / 2; 
    } else {
        // If n is odd, return middle element
        return arr[n/2];
    }
}

