    std::cin >> a >> b >> c;

    if (a == 0 && b == 0) {
        std::cout << "Invalid equation." << std::endl;
        return 0;
    }

    if (a == 0 && b != 0) {
        x1 = (-c / b);
        std::cout << "x1 = -c / b" << std::endl;
    }

    if (b * b - 4 * a * c < 0) {
        std::cout << "Not a real solution." << std::endl;
        return 0;
    }

    if (b * b - 4 * a * c > 0) {
        x1 = (b + sqrt(b * b - 4 * a * c)) / 2 * a;
        x2 = (b - sqrt(b * b - 4 * a * c)) / 2 * a;
        std::cout << "x1 = " << x1 << ", x2 = " << x2 << std::endl;
    }

    return 0;
}

