    }
    fn y(&self) -> i32 {
        self.lat.parse::<i32>().unwrap() * 1000
    }
}

impl Id for Event {
    fn id(&self) -> String {
        self.uid.clone()
    }
}

impl GeomFilterFields for Event {}

struct MyParser;

impl<FIELDS: GeomFilterFields> Parser<FIELDS> for MyParser {
    fn from_str(&self, line: &str) -> FIELDS {
        let mut split = line.split(',');
        let uid = split.next().unwrap();
        let lat = split.next().unwrap();
        let lon = split.next().unwrap();
        let hour = split.next().unwrap();
        Event {
            uid: uid.to_string(),
            lat: lat.to_string(),
            lon: lon.to_string(),
            hour: hour.to_string(),
        }
    }
}

fn geom_filter<FIELDS: GeomFilterFields, P: Parser<FIELDS>>(
    geom: Geom, 
