        let id = element.id();
        if geom.intersects(point) && prev_id != Some(id) {
            // Do something with line
            println!("{}", line);
            prev_id = Some(id);
        }
    }
}

fn main() {
    let parser = MyParser;
    geom_filter(Geom::new(), "events.csv", parser); 
}
