```cpp
#include <iostream>
#include <vector>
#include <queue>
using namespace std;

// Graph is represented using adjacency list 
struct Node {
    string city;
    int distance;
    vector<pair<string, int>> adjList;
};

// Utility function to find the node with minimum distance 
struct compare {
    bool operator()(Node* n1, Node* n2) {
        return n1->distance > n2->distance; 
    }
};

// NAME_1's algorithm 
void NAME_1(Node* start, string endCity) {
    // Create a min heap and insert source node into it 
    priority_queue<Node*, vector<Node*>, compare> pq; 
    pq.push(start); 
    start->distance = 0;

    // loop till min heap is empty 
    while (!pq.empty()) { 
        // Extract node with minimum distance 
        Node* minNode = pq.top(); 
        pq.pop(); 

        // If we have reached the destination city, 
        // print the path and minimum distance 
        if (minNode->city == endCity) {
            cout << "Minimum distance to " << endCity << " is " 
                 << minNode->distance << endl; 
            vector<string> path; 
            Node* current = minNode;
            while (current != start) {
                path.push_back(current->city);
                current = current->parent; 
            }
            path.push_back(start->city); 
            reverse(path.begin(), path.end());
            cout << "Path is: ";
            for (auto city : path) 
                cout << city << " -> "; 
            cout << endl; 
            return; 
        }

        // Relax adjacent vertices of the extracted vertex 
        for (auto neighbor : minNode->adjList) {
            Node* adjNode = neighbor.first;
            int weight = neighbor.second;
            if (adjNode->distance > minNode->distance + weight) {
                adjNode->distance = minNode->distance + weight; 
                adjNode->parent = minNode; 
                pq.push(adjNode); 
            }
        }
    }
}

