    val filePath = new Path("/input/file.csv")
    val fileSystem = FileSystem.get(spark.sparkContext.hadoopConfiguration)
    val csvFile = fileSystem.open(filePath)
    val schema = csvFile.getSchema
    val data = csvFile.collect()
