    val hbaseConnection = DriverManager.getConnection(
      "jdbc:hbase:ip_table",
      "username",
      "password"
    )

    // Insert data into HBase table
    val columns = schema.fieldNames.toSeq
    val rowData = data.map(row => (columns.map(c => row.get(c)).toSeq))
    rowData.foreach(rows => {
      val stmt = new StringBuffer
      stmt.append("INSERT INTO ip_table (")
      stmt.append(columns.map(c => "col_" + c).mkString(", "))
      stmt.append(") VALUES (")
      stmt.append(rows.map(r => "'" + r.map(v => if (v == null) "" else v.toString).mkString("', '")).mkString(", "))
      stmt.append(")")
      hbaseConnection.createStatement().execute(stmt.toString)
    })

    // Close HBase connection
    hbaseConnection.close()

    // Stop Spark Session
