```rust
use std::cmp;

fn gaussian_moving_average(data: &[f64], window_size: usize, sigma: f64) -> Vec<f64> {
    let half_window = (window_size - 1) / 2;
    let mut weights = Vec::with_capacity(window_size);
    let mut sum = 0.0;

    // Calculate the weights using the Gaussian distribution formula
    for i in 0..window_size {
        let x = (i as isize - half_window as isize) as f64;
        let weight = (-x * x / (2.0 * sigma * sigma)).exp();
        weights.push(weight);
        sum += weight;
    }

    // Normalize the weights
    for weight in &mut weights {
        *weight /= sum;
    }

    let data_len = data.len();
    let mut result = Vec::with_capacity(data_len);

    // Apply the moving average filter
    for i in 0..data_len {
        let start = cmp::max(i as isize - half_window as isize, 0) as usize;
        let end = cmp::min(i + half_window + 1, data_len);
        let mut average = 0.0;

        for j in start..end {
            average += data[j] * weights[j - start];
        }

        result.push(average);
    }

    result
