Sure! Here is the basic implementation of quicksort in C++:
```c
#include <iostream>
#include <algorithm>

using namespace std;

void quicksort(int arr[], int left, int right) {
    if (left < right) {
        int pivot = partition(arr, left, right);
        quicksort(arr, left, pivot - 1);
        quicksort(arr, pivot + 1, right);
    }
}

int partition(int arr[], int left, int right) {
    int pivot = arr[right];
    int i = left - 1;
    for (int j = left; j <= right; j++) {
        if (arr[j] <= pivot) {
            i++;
            swap(arr[i], arr[j]);
        }
    }
    swap(arr[i + 1], arr[right]);
    return i + 1;
}

int main() {
    int arr[] = {4, 6, 2, 1, 5, 3};
    int n = sizeof(arr) / sizeof(arr[0]);
    quicksort(arr, 0, n - 1);
    cout << "Sorted array: ";
    for (int i = 0; i < n; i++) {
        cout << arr[i] << " ";
    }
    cout << endl;
    return 0;
}
```
In this code, the `quicksort` function is used to sort an array `arr` with `left` and `right` indices. The pivot element is chosen as the last element in the array, but it can be any element. The `partition` function is used to divide the array into two parts around the pivot, with all elements less than the pivot in the left part and all elements greater than the pivot in the right part. The pivot element itself is placed in the middle of the two parts. Finally, the `quicksort` function is called recursively on the left and right parts of the array.

