    push(); 
    translate(x, y);
    rotate(frameCount * 0.01);

    let shapeType = floor(random(4));
    if (shapeType === 0) this.drawLine(this.gridSize * 0.8);
    else if (shapeType === 1) this.drawTriangle(this.gridSize * 0.8); 
    else if (shapeType === 2) this.drawSquare(this.gridSize * 0.8);
    else if (shapeType === 3) this.drawCircle(this.gridSize * 0.8);

