Aquí hay un ejemplo de código Go que crea un servidor de tipo OCNI Fiber utilizando la biblioteca 'fiber' y la biblioteca 'net'. Este servidor simplemente escucha en un puerto determinado y recibe conexiones.
```go
package main

import (
    "fmt"
    "log"
    "net"
    "sync"

    "github.com/ocnus/gofiber/fiber"
)

func main() {
    // Configuración de la conexión de red
    listener, err := net.Listen("tcp", ":8080")
    if err != nil {
        log.Fatal(err)
    }
    defer listener.Close()

    // Crear un fiber que maneje la conexión y el servidor
    connections := make(map[*net.TCPConn]bool)
    fiber.CurrentContext().Register("connections", connections)
    go func() {
        for {
            // Esperar por una conexión entrante
            conn, err := listener.Accept()
            if err != nil {
                log.Println(err)
                continue
            }
            // Agregar la conexión al mapa de conexiones
            connections[conn] = true
            // Hacer un bucle de lectura en el fiber
            go func(conn *net.TCPConn) {
                for {
                    // Leer el flujo de datos del cliente
                    _, err = conn.Read(make([]byte, 1024))
                    if err != nil {
                        log.Println(err)
                        return
                    }
                    // Procesar el flujo de datos leído
                    fmt.Println("Recibido:", string(conn.Reader.String()))
                }
            }(conn)
        }
    }()

    // Implementar el servidor de tipo OCNI Fiber
    fiber.Run()
}
```
