```php
function drawLabel(text, size, bgGradient, radius) {
  // Create the canvas and context
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');

  // Set the canvas size
  canvas.width = size;
  canvas.height = size;

  // Set the gradient background
  ctx.beginPath();
  ctx.arc(size / 2, size / 2, radius, 0, 2 * Math.PI);
  ctx.fillStyle = bgGradient;
  ctx.fill();

  // Set the font and text size
  ctx.font = size + 'px sans-serif';

  // Calculate the text position based on the size and radius
  let x = size / 2;
  let y = size / 2;
  let textWidth = ctx.measureText(text).width;
  if (radius > textWidth / 2) {
    x -= radius - textWidth / 2;
    y += radius - textWidth / 2;
  }

  // Draw the text
  ctx.fillStyle = 'black';
  ctx.fillText(text, x, y);

  // Return the canvas
  return canvas;
}
```
