import React, { useState, useEffect } from 'react';

const CSVFile = () => {
  // Declare state variables to hold the headers and data types
  const [headers, setHeaders] = useState([]);
  const [dataTypes, setDataTypes] = useState([]);

  // Use the useEffect hook to read the headers and data types from the CSV file
  useEffect(() => {
    const file = new File([headers], 'headers.csv', { type: 'text/csv' });
    fetch('fetch-headers.php', {
      method: 'POST',
      body: JSON.stringify({ file }),
      headers: { 'Content-Type': 'multipart/form-data' }
    })
      .then(response => response.json())
      .then(data => {
        setHeaders(data.headers);
        setDataTypes(data.types);
      })
      .catch(error => console.log(error));
  }, []);

  return (
    <div>
      <h1>Headers and Data Types</h1>
      {headers.map(header => (
        <div key={header}>
          <p>Header: {header}</p>
          <p>Data Type: {dataTypes[header - 1]}</p>
        </div>
      ))}
    </div>
  );
}

export default CSVFile;
