Here's a function in Go that finds the start index where all the bytes from the second slice match in the first slice. This implementation uses the Boyer-Moore algorithm for improved performance:

```go
package main

import (
	"fmt"
)

// Generate bad character rule table
func generateBadCharTable(pattern []byte) map[byte]int {
	table := make(map[byte]int)
	for i, c := range pattern {
		table[c] = i
	}
	return table
}

// Boyer-Moore search algorithm
func findBytesBM(haystack, needle []byte) int {
	if len(needle) == 0 {
		return 0
	}

	badCharTable := generateBadCharTable(needle)
	haystackLen := len(haystack)
	needleLen := len(needle)
	offset := 0

	for offset <= haystackLen-needleLen {
		j := needleLen - 1

		for haystack[offset+j] == needle[j] {
			if j == 0 {
				return offset
			}
			j--
		}

		offset += needleLen - 1
		if j < offset {
			if badCharIndex, ok := badCharTable[haystack[offset]]; ok {
				offset -= badCharIndex
			} else {
				offset++
			}
		}
	}

	return -1
}

func main() {
	haystack := []byte("I love programming in Go")
	needle := []byte("programming")
	result := findBytesBM(haystack, needle)
	fmt.Println(result) // 7
}
```

This function should give you better performance compared to a naive search algorithm, especially for larger input sizes.

