```sql
procedure BubbleSort(var Array: array[1..ArraySize-1] of Integer);
var
  i, j: Integer;
  N: Integer;
begin
  N := ArraySize;
  for i := 0 to N-1 do
  begin
    for j := 0 to N-1 do
    begin
      if Array[j] > Array[j+1] then
      begin
        SetArray(j, Array[j+1]);
        Array[j+1] := Array[j];
      end
    end;
  end;
end;
```
