Here's a possible implementation of the radix sort algorithm in C++17:
```cpp
#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

void radixSort(vector<int>& arr, int n) {
    int max_digit = 0;
    for (int i = 0; i < n; i++) {
        max_digit = max(max_digit, arr[i] >= 10 ? 9 : 0);
    }

    int digits[10];
    for (int i = 0; i < n; i++) {
        digits[arr[i] / 10]++;
    }

    int count[10];
    for (int i = 0; i < 10; i++) {
        count[i] = 0;
        for (int j = 0; j < n; j++) {
            if (digits[j] > 0) {
                count[i]++;
            }
        }
    }

    int temp[10][10];
    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < 10; j++) {
            temp[i][j] = 0;
        }
    }

    for (int i = 0; i < n; i++) {
        int digit = arr[i] % 10;
        temp[digit][count[digit] - 1] = arr[i];
        count[digit]--;
    }

    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < 10; j++) {
            for (int k = 0; k < 10; k++) {
                if (temp[i][k] != 0) {
                    arr[temp[i][k] - 1] = temp[i][k];
                }
            }
        }
    }
}

