#include <stdio.h>
#include <stdint.h>
#include <string.h>

#define CRC_POLYNOM 0x1021

uint16_t calculate_checksum(const uint8_t *data, size_t length) {
    uint16_t crc = 0xFFFF;
    for (size_t i = 0; i < length; i++) {
        crc = crc ^ data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x0001) {
                crc = (crc >> 1) ^ CRC_POLYNOM;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

