In C#, you can parse command line arguments using the `CommandLineArgs` NuGet package, which provides a set of classes and methods to parse command line arguments in a cross-platform way.

Here's an example of how to use `CommandLineArgs` to parse command line arguments in C#:
```csharp
using System;
using System.Linq;
using CommandLineArgs;

class Program {
    static void Main(string[] args) {
        // define the command line arguments
        var commandLineArgs = CommandLineArgs.Parse<CommandLineArgs>();

        // get the value of the first argument
        var firstArgument = commandLineArgs.GetRequired<string>("firstArgument");

        // get the value of the second argument
        var secondArgument = commandLineArgs.GetRequired<int>("secondArgument");

        // get the value of the third argument
        var thirdArgument = commandLineArgs.GetOptional<string>("thirdArgument");

        // get the values of all arguments
        var allArguments = commandLineArgs.GetAllStrings();

        // check if a specific argument was provided
        if (commandLineArgs.Contains("specificArgument")) {
            var specificArgument = commandLineArgs.GetRequired<string>("specificArgument");
            Console.WriteLine("Specific argument provided: " + specificArgument);
        }

        // check if an optional argument was provided
        if (commandLineArgs.Contains("optionalArgument")) {
            var optionalArgument = commandLineArgs.GetOptional<int>("optionalArgument");
            if (optionalArgument.HasValue) {
                Console.WriteLine("Optional argument provided: " + optionalArgument.Value);
            } else {
                Console.WriteLine("No optional argument provided");
            }
        }

        // print all arguments
        Console.WriteLine("All arguments: " + string.Join(", ", allArguments));

        Console.WriteLine();
    }
}
