function randomWithNoise() {
  // Get a random number between 0 and 1
  const r = Math.random();

  // Add some noise to the random number
  const noise = Math.random() * 0.1;

  // Scale the random number to be between 0 and 1
  const result = Math.min(Math.max(r + noise, 0), 1);

  // Return the noisy random number
