int _tmain(int argc, _TCHAR* argv[])
{
    HWND hSerialPort;
    _TCHAR serialPortName[64] = _T("COM1");
    UART_CONFIG_DATA uartConfig;
    _TCHAR productName[64];

    // Initialize the serial port configuration data structure
    uartConfig.hwPortAddress = serialPortName;
    uartConfig.baudRate = 9600;
    uartConfig.dataBits = 8;
    uartConfig.stopBits = ONESTOPBIT;
    uartConfig.parity = NOPARITY;

    // Open the serial port
    hSerialPort = CreateSerialPort(NULL, &uartConfig, sizeof(uartConfig), &hSerialPort);
    if (hSerialPort == NULL)
    {
        _tprintf(_T("Failed to create serial port. Error is %d\n"), GetLastError());
        return 1;
    }

    // Get the product name from the serial port
    if (GetSerialPortProperty(hSerialPort, SERIAL_PROP_PRODUCT_NAME, productName, sizeof(productName)) == FALSE)
    {
        _tprintf(_T("Failed to get serial port property. Error is %d\n"), GetLastError());
        CloseSerialPort(hSerialPort);
        return 1;
    }

    _tprintf(_T("Product name: %s\n"), productName);

    // Close the serial port
    CloseSerialPort(hSerialPort);

    return 0;
}
