public class MainActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        // Get a reference to the toggle button
        ToggleButton toggleButton = findViewById(R.id.toggleButton);

        // Set the initial state of the button to unpressed
        toggleButton.setChecked(false);

        // Set a listener for the button
        toggleButton.setOnCheckedChangeListener(new ToggleButton.OnCheckedChangeListener() {
            @Override
            public void onCheckedChanged(ToggleButton toggleButton, boolean isChecked) {
                // If the button is clicked, toggle its state
                if (isChecked) {
                    toggleButton.setTextColor(getResources().getColor(R.color.pressed_color));
                    toggleButton.setBackgroundColor(getResources().getColor(R.color.pressed_color));
                } else {
                    toggleButton.setTextColor(getResources().getColor(R.color.unpressed_color));
                    toggleButton.setBackgroundColor(getResources().getColor(R.color.unpressed_color));
                }
            }
        });
    }
}
```

This program defines an `AppCompatActivity` that contains a `ToggleButton` with the ID `toggleButton`. When the button is clicked, the program toggles the state of the button (unpressed to pressed, or pressed to unpressed), and updates the button text color and background color accordingly.

