Here is an Express middleware that will log response times to a JSON file per day:
```js
const fs = require('fs');
const path = require('path');

const logger = (req, res, next) => {
  const startTime = Date.now();
  const date = new Date();
  const dateStr = date.toISOString().split('T')[0];
  const logFile = path.join(__dirname, 'logs', `${dateStr}.json`);

  fs.appendFile(logFile, '[' , (err) => {
    if (err) throw err;
  });  

  const oldWrite = res.write;
  const oldEnd = res.end;

  res.write = (...args) => {
    oldWrite.apply(res, args);
  }

  res.end = (...args) => {
    const endTime = Date.now();
    const responseTime = endTime - startTime;

    const log = {
      timestamp: Date.now(),
      method: req.method, 
      path: req.path, 
      responseTime,
      req: { headers: req.headers, body: req.body },
      res: { statusCode: res.statusCode, headers: res.getHeaders() } 
    }

    fs.appendFile(logFile, JSON.stringify(log) + ',' , (err) => {
      if (err) throw err;
    });  

    oldEnd.apply(res, args);

    fs.appendFile(logFile, ']' , (err) => {
      if (err) throw err;
    });  
  }

  next();
}

module.exports = logger;
```

This middleware does the following:

- Gets the current date and constructs a log file path
- Appends a [ to the log file to start the JSON array 
- Overwrites the res.write and res.end methods to log the response time and full request/response info
- Appends the log object as JSON to the file, followed by a , 
- Finally appends a ] to close the JSON array
- Calls next() to continue handling the request

