    let mut message = String::from("Hello, World!");

    // Create a new module and set the `message` field
    let mut module = Module::new();
    module.set("message", message);

    // Execute the module and get the result
    let result = module.execute();

    // Extract the `message` from the result
    let message = result.get("message").unwrap();

    // Return the `HelloWorld` struct with the message
    return HelloWorld {
        message: message,
    };
}
