function isRomanNumeral(str) {
  // Create a lookup table for Roman numeral symbols and their values.
  const lookup = {
    'I': 1,
    'V': 5,
    'X': 10,
    'L': 50,
    'C': 100,
    'D': 500,
    'M': 1000,
  };

  // Convert the string to lowercase.
  str = str.toLowerCase();

  // Initialize a running total of the value of the Roman numerals in the string.
  let total = 0;

  // Iterate over the characters in the string.
  for (let i = 0; i < str.length; i++) {
    // Get the value of the current Roman numeral symbol.
    const value = lookup[str[i]];

    // If the current Roman numeral symbol is the same as the previous one, add its value to the total only if it is preceded by a smaller value.
    if (i > 0 && str[i] === str[i - 1] && value <= lookup[str[i - 1]]) {
      total += value;
    } else {
      // Otherwise, add the value of the current Roman numeral symbol to the total.
      total += value;
    }
  }

  // Return true if the total value of the Roman numerals in the string is a valid integer.
  return Math.floor(total) === total;
}
