```go
package main

import (
    "fmt"
    "net"
)

func portScan(host string, port int) error {
    // Resolve host address
    ip := net.ParseIP(host)
    if ip == nil {
        return fmt.Errorf("invalid host address: %s", host)
    }

    // Open listener on loopback interface
    listener, err := net.Listen("tcp", "127.0.0.1:0")
    if err != nil {
        return err
    }
    defer listener.Close()

    // Use conn.(*TCPConn). syn to SYN scan the port
    for _, port := range []int{80, 443, 1337, 27015, 8080, 3000} {
        fmt.Printf("Scanning port %d on %s...\n", port, host)
        conn, err := listener.Accept()
        if err != nil {
            return err
        }
        defer conn.Close()

        // Send SYN
        _, err = conn.(*TCPConn).Write([]byte{byte(syscall.SYN), 0, 0, 0, 0, 0, 0, 0, 0, 0})
        if err != nil {
            return err
        }

        // Wait for response
        _, err = conn.(*TCPConn).Read(make([]byte, 1))
        if err != nil {
            return err
        }

        // Check for open port
        if conn.(*TCPConn).(*conn).state == "ESTABLISHED" {
            fmt.Println("Port open")
        } else {
            fmt.Println("Port closed")
        }
    }

    return nil
}

func main() {
    // Example usage
    portScan("example.com", 80)
}
