	"io/ioutil"
)

type HTTPHandler interface {
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type FileServer struct {
	http.Handler
}

func (s *FileServer) ServeHTTP(w http.ResponseWriter, r *http.Request) {
