type TimedDict map[string]time.Time

func NewTimedDict() *TimedDict {
	return &TimedDict{make(map[string]time.Time)}
}

func (td *TimedDict) Add(key, value string) {
	td.store(key, time.Now())
}

func (td *TimedDict) store(key string, value time.Time) {
	td.Lock()
	defer td.Unlock()
	if current, exists := td.m[key]; exists && current.Before(value.Add(5 * time.Minute)) {
		td.m[key] = value
	} else {
		delete(td.m, key)
	}
}

func (td *TimedDict) Check() {
	for {
		time.Sleep(5 * time.Second)
		td.Lock()
		defer td.Unlock()
		for key := range td.m {
			if td.m[key].Add(5 * time.Minute).Before(time.Now()) {
				delete(td.m, key)
			}
		}
	}
}

