```javascript
(function() {
  var storage = localStorage;

  /**
   * store data in local storage with a given key
   * @param {string} key - the key to store data under
   * @param {string} value - the value to store
   */
  function set(key, value) {
    storage.setItem(key, JSON.stringify(value));
  }

  /**
   * get data from local storage with a given key
   * @param {string} key - the key to get data from
   * @return {string|null} the value stored under the key, or null if not found
   */
  function get(key) {
    var item = storage.getItem(key);
    return item ? JSON.parse(item) : null;
  }

  /**
   * listen for changes to local storage
   * @param {function} listener - a function to be called when data is added, updated, or removed
   */
  function listen(listener) {
    if (typeof listener !== 'function') {
      console.error('listener must be a function');
      return;
    }
    var self = this;
    var change = function() {
      var keys = Object.keys(storage);
      keys.forEach(function(key) {
        var value = storage.getItem(key);
        if (value !== null) {
          listener(key, value);
        }
      });
    };
    change();
    setTimeout(change, 0);
  }

  return {
    set: set,
    get: get,
    listen: listen
  };
})();
```
