            ai_score += 1;
            println!("AI wins! Score: You - {} | AI - {}", player_score, ai_score);
        }

        if player_score == 5 || ai_score == 5 {
            println!("Game over! ");
            if player_score > ai_score {
                println!("You won the game!");
            } else {
                println!("AI won the game!");
            }
            break;
        }
    }
}
