#include <iostream>

using namespace std;

void printSubarrays(int arr[], int n) {
    int i, j, k, sub[] = {0};
    for (i = 0; i < n - 1; i++) {
        for (j = i + 1; j < n; j++) {
            k = 0;
            while (k < n && arr[i] + k <= arr[j]) {
                sub[k] = arr[i] + k;
                k++;
            }
            if (k == n || sub[k] < arr[j]) {
                cout << "Subarray from index " << i << " to " << j << " is " << sub << endl;
            }
        }
    }
}

