void push_back(vector* self, void* element) {
    if (self->size == self->capacity) {
        // Increase the capacity of the vector
        size_t new_capacity = self->capacity * 2;
        void** new_data = realloc(self->data, new_capacity * sizeof(void*));
        if (new_data == NULL) {
