  if (gsm.available()) {
    char input = gsm.read();
    if (input == '\r') {
      gsm.print("AT+CPT?");
      delay(1000);
      gsm.print("AT+CPT=?");
      delay(1000);
      gsm.print("AT+CPT=?");
