// @author       You
// @match        *://*/*
// @grant        none
// ==/UserScript==

(function() {
    'use strict';

    // Wait for the first tab to finish loading
    const waitForFirstTab = setInterval(() => {
        const firstTab = document.querySelector('[role="tabpanel"]:not([tabindex="0"]):not([aria-hidden="true"])');
        if (firstTab) {
            clearInterval(waitForFirstTab);
            setTimeout(() => {
                // Go to the second tab
                const secondTab = document.querySelector('[role="tabpanel"][tabindex="0"]');
                if (secondTab) {
