To download files from an FTP server using FluentFTP in C#, you can follow these steps:

1. First, you need to install the FluentFTP NuGet package. You can do this by opening your Visual Studio, right-clicking on your project and selecting "Manage NuGet Packages for Solution". Then search for "FluentFTP" and click Install.
2. After installing FluentFTP, you can use the following code to download files:
```csharp
using System;
using System.IO;
using System.Threading.Tasks;
using FluentFTP;

namespace FTPDownloadExample
{
    class Program
    {
        static async Task Main(string[] args)
        {
            var config = new FluentFTP.Config
            {
                Host = "ftp.example.com",
                UserName = "your_username",
                Password = "your_password",
                EncryptionMode = EncryptionMode.Explicit,
                SslProtocols = SslProtocols.Tls12
            };

            using (var client = new FtpClient(config))
            {
                await client.ConnectAsync();

                string remoteFilePath = "path/to/remote/file.ext";
                string localFolder = "path/to/local/folder";

                await client.GetFilesAsync(remoteFilePath, localFolder);

                Console.WriteLine($"Downloaded {remoteFilePath} to {localFolder}");
            }
        }
    }
}
```
Replace `ftp.example.com` with the FTP server's address, `your_username` and `your_password` with your FTP credentials, and `path/to/remote/file.ext` and `path/to/local/folder` with the appropriate paths.

