    {
        // Get intersection points of subject polygon and clip polygon
        List<Point> intersectionPoints = GetIntersections(subjectPolygon, clipPolygon);

        // Add intersection points to result
        List<Point> result = new List<Point>();
        result.AddRange(intersectionPoints);

        // Add points from subject polygon up to first intersection 
        Point prev = subjectPolygon.Last();
        foreach (Point curr in subjectPolygon) 
