If you always want to delete from the tail of a data structure, a Singly Linked List would be a better choice than an Array. This is because an array has a fixed size, which means that if you want to add or delete elements after the array is full, you have to create a new array with a larger size and copy the elements over. This can be time-consuming and memory-intensive.

A Singly Linked List, on the other hand, can easily accommodate additional elements at the end of the list, without requiring any additional memory or copying of elements. This makes it a more efficient choice for situations where you need to frequently add or delete elements from the tail of the list.

Here's an example code in C++ for a Singly Linked List:
```c++
#include <iostream>
using namespace std;

// Define a node for the linked list
struct Node {
   int data;
   Node* next;
};

// Function to insert a new node at the end of the linked list
Node* insertNode(Node*& head, int data) {
   Node* newNode = new Node;
   newNode->data = data;
   newNode->next = NULL;
   if (head == NULL) {
      head = newNode;
      return head;
   } else {
      Node* temp = head;
      while (temp->next != NULL) {
         temp = temp->next;
      }
      temp->next = newNode;
      return head;
   }
}

// Function to delete the last node of the linked list
Node* deleteNode(Node*& head) {
   if (head == NULL) {
      return head;
   } else {
      Node* temp = head;
      while (temp->next != NULL) {
         temp = temp->next;
      }
      Node* prev = temp;
      Node* curr = temp->next;
      while (curr != NULL) {
         prev->next = curr->next;
         curr = curr->next;
      }
      delete temp;
      return head;
   }
}

