    y: i32,
    r: i32,
}

impl Geom {
    fn intersects(&self, point: &Point) -> bool {
        let dx = self.x - point.x;
        let dy = self.y - point.y;
        let d = dx * dx + dy * dy;
        let r2 = self.r * self.r;
        d <= r2
    }
}

