        let id = fields.next().unwrap().to_string();
        let x = fields.next().unwrap().parse().unwrap();
        let y = fields.next().unwrap().parse().unwrap();
        GeomFilterFields {
            id,
            xy: Point { x, y },
        }
    }
}

