public class ObjectAlwaysUpright : MonoBehaviour
{
    public float force = 10.0f;
    public float updateInterval = 0.1f;

    private Rigidbody rb;
    private bool isUpright = true;

    void Start()
    {
        rb = GetComponent<Rigidbody>();
    }

