```php
function bubble_sort(array $NAME_1): void {
    $n = count($NAME_1);

    for ($i = 0; $i < $n - 1; $i++) {
        for ($j = 0; $j < $n - $i - 1; $j++) {
            if ($NAME_1[$j] > $NAME_1[$j + 1]) {
                $temp = $NAME_1[$j];
                $NAME_1[$j] = $NAME_1[$j + 1];
                $NAME_1[$j + 1] = $temp;
            }
        }
    }
}
```
