    ifstream infile(filename);
    if (!infile.is_open()) {
        cout << "Error: Could not open file " << filename << endl;
        return 1;
    }

    unordered_map<string, int> word_indices;

    string line;
    while (getline(infile, line)) {
        int start = findFirstNonWhitespace(line);
        int end = start + line.size() - 1;
        while (end >= start && isspace(line[end])) {
            end--;
        }

        string word = line.substr(start, end - start);
        if (word_indices.count(word) == 0) {
            cout << word << endl;
            word_indices[word] = 0;
        }
        word_indices[word] += 1;
