```sql
-- Backup database script

-- Get database name 
SELECT DATABASE();

-- Create backup folder if not exists 
CREATE TABLE IF NOT EXISTS `backups` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

-- Get backup folder path 
SELECT @@datadir;

-- Create backup file name with timestamp 
SET @backup_file = CONCAT(DATABASE(), '_', REPLACE(NOW(), ' ', '_'), '.sql');

-- Create backup file 
SELECT @backup_file;
SELECT CONCAT('mysqldump -u root -p', DATABASE(), ' > ', @backup_file) 
INTO OUTFILE '/tmp/backup.sh';

-- Make backup file executable 
SELECT CONCAT('chmod +x /tmp/backup.sh') 
INTO OUTFILE '/tmp/chmod.sh';

-- Execute backup file to get actual backup 
SOURCE /tmp/chmod.sh; 
SOURCE /tmp/backup.sh; 

-- Delete temporary files 
SELECT CONCAT('rm -f /tmp/backup.sh /tmp/chmod.sh') 
INTO OUTFILE '/tmp/delete.sh';

SOURCE /tmp/delete.sh;
```

