```java
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class MoveObject : MonoBehaviour
{
    // The speed at which the object moves
    public float speed = 5.0f;

    // Update is called once per frame
    void Update()
    {
        // Get the horizontal and vertical axes
        float horizontal = Input.GetAxis("Horizontal");
        float vertical = Input.GetAxis("Vertical");

        // Create a Vector3 object for the direction we want to move
        Vector3 direction = new Vector3(horizontal, 0, vertical);

        // Normalize the direction vector so we can move at a consistent speed
        direction = Vector3.Normalize(direction);

        // Move the object in the direction we calculated
        transform.position += direction * speed * Time.deltaTime;
    }
