        arr[i] = i;  // initialise the array
    }
    for (i = 0; i < n-1; i++) {
        for (j = i+1; j < n; j++) {
            if (arr[j] > arr[i]) {
                bubbleSort(arr, n);  // sort the elements
                for (i = 0; i < n; i++) {
