function extractFileFromZip(zipFilePath, filePath) {
  const fs = require('fs');
  const AdmZip = require('adm-zip');

  // Read the zip file
  const zip = new AdmZip(zipFilePath);
  const zipEntries = zip.getEntries();

  // Find the file entry
  const fileEntry = zipEntries.find(entry => entry.name === filePath);

  // Extract the file to the specified directory
  const directory = fileEntry.getSourceFile().dir;
  fs.mkdirSync(directory, { recursive: true });
  fileEntry.getSourceFile().extract(directory);

  return true;
}
