Here is a quick implementation of quicksort in C++:
```cpp
void quicksort(int arr[], int low, int high) {
    if (low < high) {
        // partition the array around pivot arr[high]
        int pivot = arr[high];
        int i = low - 1;

        for (int j = low; j <= high - 1; j++) {
            if (arr[j] < pivot) {
                i++;
                swap(arr[i], arr[j]);
            }
        }
        swap(arr[i + 1], arr[high]);

        // recursively sort left and right halves
        quicksort(arr, low, i);
        quicksort(arr, i + 2, high);
    }
}

void swap(int &a, int &b) {
    int temp = a;
    a = b;
    b = temp; 
}

int main() {
    int arr[] = {3, 1, 4, 9, 5, 2};
    int n = sizeof(arr) / sizeof(arr[0]);

    quicksort(arr, 0, n - 1);

    for (int i = 0; i < n; i++) 
        cout << arr[i] << " ";
}
```

This implements the quicksort algorithm to sort the array arr. The quicksort function partitions the array around the pivot (last element) and recursively calls itself to sort the left and right partitions. The swap function is used to swap two elements.

