public class Food : IComparable<Food>
{
    public int Value { get; set; }
    public int Quantity { get; set; }

    public int CompareTo(Food other)
    {
        return other.Value - Value;
    }
}

public class ResourceManager
{
    private readonly List<Food> _food = new List<Food>();

    public void AddFood(Food food)
    {
        _food.Add(food);
    }

    public Food GetFood(int quantity)
    {
        var food = _food.OrderBy(f => f.Value - f.Quantity).FirstOrDefault();
        if (food == null)
        {
            food = new Food();
            food.Value = 0;
            food.Quantity = quantity;
            _food.Add(food);
        }
        else if (food.Quantity < food.Value)
        {
            food.Quantity += quantity;
        }
        else
        {
            food.Value -= food.Quantity;
            food.Quantity = quantity;
        }
        return food;
    }
}
```
