```csharp
public static int BinarySearch(List<string> list, string target)
{
    int start = 0;
    int end = list.Count - 1;

    while (start <= end)
    {
        int mid = start + (end - start) / 2;

        if (list[mid] == target)
        {
            return mid;
        }
        else if (list[mid] < target)
        {
            start = mid + 1;
        }
        else
        {
            end = mid - 1;
        }
    }

    return -1;
}
```
