#include <iostream>
#include <fstream>
#include <cstring>

class BufferedStream {
public:
    BufferedStream(std::ifstream& stream, const std::string& buffer_size) {
        _stream = stream;
        _buffer = new char[buffer_size];
        _read_count = 0;
    }

    ~BufferedStream() {
        delete[] _buffer;
    }

    std::istream& read() {
        // Read data from the underlying input stream.
        auto n = _stream.read(_buffer, _read_count);
        if (n > 0) {
            _read_count += n;
            return *this;
        }
        return std::istream();
    }

    std::ostream& write(const char* data, std::streamsize length) {
        // Write data to the underlying output stream.
        if (length > 0 && _write_count < _buffer_size) {
            _stream.write(data, length);
            _write_count += length;
        }
        return *this;
    }

private:
    std::ifstream& _stream;
    char* _buffer;
    std::streamsize _buffer_size;
    std::streamsize _read_count;
    std::streamsize _write_count;
};
```
