        currentSize = transform.localScale.x;
    }

    void Update() {
        if (Input.GetMouseButtonDown(0)) {
            startTime = Time.time;
            isHovering = false;
        } else if (Input.GetMouseButton(0)) {
            float timeSinceClick = Time.time - startTime;
