Here's a simple implementation of the Two Sum algorithm in JavaScript:
```javascript
function twoSum(arr, target) {
  let left = 0;
  let right = arr.length - 1;
  while (left <= right) {
    let sum = arr[left] + arr[right];
    if (sum === target) {
      return [arr[left], arr[right]];
    } else if (sum < target) {
      left++;
    } else {
      right--;
    }
  }
  return [-1, -1];
}

