public static List<T> Materialize<T>(this IEnumerable<T> source, int skip = 0, int take = int.MaxValue)
	{
		if(skip == 0 && take == 0)
		{
			_ = source.ToList();
			return new List<T>(0);
		}

		if(skip == 0 && take == int.MaxValue)
		{
			return source.ToList();
		}

		return source
			.Skip(skip)
			.Take(take)
			.ToList();
	}

