```c++
#include <algorithm>
#include <iostream>
#include <vector>

std::pair<int, int> largestDifference(const std::vector<int>& arr) {
    std::sort(arr.begin(), arr.end());
    int maxDifference = 0;
    int maxDifferenceIndex = 0;
    for (int i = 0; i < std::abs(arr[0] - arr[1]); i++) {
        maxDifference = std::max(maxDifference, arr[i + 1] - arr[i]);
        if (arr[i + 1] > arr[maxDifferenceIndex]) {
            maxDifferenceIndex = i + 1;
        }
    }
    return std::make_pair(maxDifference, maxDifferenceIndex);
}

int main() {
    std::vector<int> arr = {3, 5, 1, 9, 2, 6, 8, 10, 4};
    std::pair<int, int> maxDifference = largestDifference(arr);
    std::cout << "The two numbers with the largest difference are " << maxDifference.first << " and " << maxDifference.second << std::endl;
    return 0;
}
```
