            buf_full = true;
            buf_cycle += 1;
            bit_left = bitwise_location;
            bit_fill_left = arr_n[i] >> (SIZE_PARSING - bit_left);
            buf |= bit_fill_left;

            println!("Value: {}", buf);

            // Reset the buffer and update the bitwise_location
            buf = 0;
            bitwise_location = SIZE_BUFFER - (SIZE_PARSING - bit_left);

            // Reset buf_cycle if it's a multiple of SIZE_PARSING
            if buf_cycle % SIZE_PARSING == 0 {
                buf_cycle = 0;
            }
        } else {
