function calculateResistanceAndSupport(prices) {
  const resistance = [];
  const support = [];

  prices.forEach((price) => {
    const currentPrice = price.Close;
    const previousPrice = prices[prices.indexOf(price) - 1].Close;

    if (price.High > previousPrice) {
