```c++
#include <atomic>
#include <functional>
#include <thread>

template <typename T>
class LockFreeFIFO {
public:
    void push(T const& value) {
        std::atomic::store(value, head.load(std::memory_order_relaxed));
        head.store(value, std::memory_order_relaxed);

        if (head.load(std::memory_order_relaxed) == tail.load(std::memory_order_relaxed)) {
            tail.store(value, std::memory_order_relaxed);
        }
    }

    T pop() {
        std::atomic::load(head.load(std::memory_order_relaxed));
        return head.load(std::memory_order_relaxed);
    }

private:
    std::atomic head{0, std::memory_order_relaxed};
    std::atomic tail{0, std::memory_order_relaxed};
};

int main() {
    LockFreeFIFO<int> fifo;
    std::thread producer([](){
        for (int i = 0; i < 10; i++) {
            fifo.push(i);
        }
    });
