        for (int i = 0; i < 20; i++)
        {
            taskCounter.IncrementTaskCount();
            // Simulate task work here
            Thread.Sleep(1000);
            taskCounter.DecrementTaskCount();
        }

        taskCounter.WaitUntilZero();

        Console.WriteLine("All tasks have finished.");
    }
}
```
