```kotlin
fun bubbleSort(arr: Array<Int>): Array<Int> {
    for (i in arr.size - 1 downTo 1) {
        for (j in i downTo 1) {
            if (arr[j] > arr[j - 1]) {
                val temp = arr[j - 1]
                arr[j - 1] = arr[j]
                arr[j] = temp
            }
        }
    }
    return arr
}
