void blink(int on) {
  int i = 0;
  while (i < 255) {
    int j = 255;
    int result = j - on;
    if (result > 0) {
      digitalWrite(9, HIGH);
      delay(1);
      digitalWrite(9, LOW);
      delay(1);
    } else {
      digitalWrite(9, LOW);
      delay(1);
      digitalWrite(9, HIGH);
      delay(1);
    }
    i++;
  }
}

