Here is a basic VST plugin that implements a ping pong delay:
```cpp
#include "public.sdk/source/vst2.x/audioeffectx.h"

enum Params {
  kDryWet = 0,
  kFeedback,
  kTime,
  kNumParams 
};

class PingPongDelay : public AudioEffectX {
public:
  PingPongDelay(audioMasterCallback audioMaster) 
    : AudioEffectX(audioMaster, kNumPrograms, kNumParams) {
    setNumInputs(2);
    setNumOutputs(2);
  }

  void process(float** inputs, float** outputs, int sampleFrames) override {
    float dryWet = *getParameter(kDryWet);
    float feedback = *getParameter(kFeedback);
    float time = *getParameter(kTime);
    int delay = (int) (time * getSampleRate() / 1000.0);

    int leftIndex = 0;
    int rightIndex = delay;

    for (int i = 0; i < sampleFrames; i++) {
      float input = inputs[0][i] + inputs[1][i];
      outputs[0][i] = input * (1.0 - dryWet) + outputs[0][leftIndex] * dryWet;
      outputs[1][i] = input * (1.0 - dryWet) + outputs[1][rightIndex] * dryWet;

      outputs[0][leftIndex] = inputs[0][i] + outputs[0][leftIndex] * feedback;
      outputs[1][rightIndex] = inputs[1][i] + outputs[1][rightIndex] * feedback; 

      leftIndex = (leftIndex + 1) % delay;
      rightIndex = (rightIndex + 1) % delay;
    }
  }
};
```

This implements the `AudioEffectX` class which is the base for VST plugins. In the `process()` method it reads the dry/wet, feedback and time parameters, calculates the delay time in samples and implements the ping pong delay effect by accessing the delayed samples in a circular buffer.

Here is the C++ code for the ping pong delay VST plugin:

```cpp
#include <cmath>
#include <cstring>

#include "audioeffectx.h"

enum Params {
  kDryWet = 0,
  kFeedback,
  kTime,
  kNumParams 
};

class PingPongDelay : public AudioEffectX {
public:
  PingPongDelay(audioMasterCallback audioMaster) 
    : AudioEffectX(audioMaster, 0, kNumParams) {
    setNumInputs(2);
    setNumOutputs(2);
    memset(outputs, 0, sizeof(outputs));
  }

  void processReplacing(float** inputs, float** outputs, int sampleFrames) override {
    float* input = inputs[0];
    float* outputL = outputs[0];
    float* outputR = outputs[1];

    float dryWet = *getParameter(kDryWet);
    float feedback = *getParameter(kFeedback);
    float time = *getParameter(kTime);
    int delay = (int) (time * getSampleRate() / 1000.0);

    int leftIndex = 0;
    int rightIndex = delay;

    for (int i = 0; i < sampleFrames; i++) {
      float in = *input++;
      *outputL++ = in * (1.0 - dryWet) + outputs[0][leftIndex] * dryWet;
      *outputR++ = in * (1.0 - dryWet) + outputs[1][rightIndex] * dryWet;

      outputs[0][leftIndex] = *input++ + outputs[0][leftIndex] * feedback;
      outputs[1][rightIndex] = *input++ + outputs[1][rightIndex] * feedback; 

      leftIndex = (leftIndex + 1) % delay;
      rightIndex = (rightIndex + 1) % delay;
    }
  }
private:
  float outputs[2][10000];
};
```

