  ctx.arc(centerX, centerY, radius, startAngle, startAngle + 2 * Math.PI);
  ctx.fillStyle = gaugeColor;
  ctx.fill();

  // Draw the needle
  ctx.beginPath();
  ctx.arc(needleCenterX, centerY, needleRadius, needleAngle[0], needleAngle[1]);
  ctx.fillStyle = needleColor;
  ctx.fill();

  // Draw the tick marks
  ctx.beginPath();
  for (let i = 0; i < numTicks; i++) {
    ctx.moveTo(tickCenterX + i * (tickSize + needleWidth), centerY);
  }
  ctx.stroke();

  // Draw the needle
  ctx.beginPath();
  ctx.arc(needleCenterX, centerY, needleRadius, needleAngle[0], needleAngle[1]);
  ctx.fillStyle = needleColor;
  ctx.fill();
}
