Sure, here's an implementation of the quicksort algorithm in C to sort an array:
```c
#include <stdio.h>
#include <stdlib.h>

void quicksort(int array[], int left, int right) {
    int i = left;
    int j = right;
    int pivot = array[(left + right) / 2];

    while (i <= j) {
        while (array[i] < pivot) {
            i++;
        }

        while (array[j] > pivot) {
            j--;
        }

        if (i <= j) {
            int temp = array[i];
            array[i] = array[j];
            array[j] = temp;
            i++;
            j--;
        }
    }

    if (left < j) {
        quicksort(array, left, j);
    }

    if (i < right) {
        quicksort(array, i, right);
    }
}

int main() {
    int array[] = {4, 6, 2, 1, 5, 3};
    int size = sizeof(array) / sizeof(array[0]);

    quicksort(array, 0, size - 1);

    for (int i = 0; i < size; i++) {
        printf("%d ", array[i]);
    }

    return 0;
}
```
In this implementation, the `quicksort` function takes an array, a left index, and a right index as input. The left and right indices specify the range of the array to be sorted. The pivot is chosen as the middle element of the array.

