Sure, here's a quicksort implementation in C++:
```c
#include <iostream>
#include <algorithm>

using namespace std;

void quicksort(int array[], int left, int right) {
    int i = left;
    int j = right;
    int pivot = array[(left + right) / 2];

    while (i <= j) {
        while (array[i] < pivot) {
            i++;
        }

        while (array[j] > pivot) {
            j--;
        }

        if (i <= j) {
            swap(array[i], array[j]);
            i++;
            j--;
        }
    }

    if (left < j) {
        quicksort(array, left, j);
    }

    if (i < right) {
        quicksort(array, i, right);
    }
}

int main() {
    int array[] = {4, 6, 2, 1, 5, 3};
    int size = sizeof(array) / sizeof(array[0]);
    quicksort(array, 0, size - 1);
    cout << "Sorted array: ";
    for (int i = 0; i < size; i++) {
        cout << array[i] << " ";
    }
    cout << endl;
    return 0;
}
```
This implementation takes an array of integers, left and right indexes, and sorts the array in ascending order using the quicksort algorithm. The pivot element is chosen as the median of the array. The function recursively divides the array into two parts, and repeatedly exchanges elements between the two parts until the pivot element is in its final position. The function calls itself recursively on the left and right halves of the array until the base case is reached, which is when the left and right halves have fewer than two elements. Finally, the sorted array is printed to the console.

