        } else if (tokens[i] == "}") {
            success--;
        } else if (tokens[i] == "[") {
            fail++;
        } else if (tokens[i] == "]") {
            fail--;
        }
    }
    if (success == 0 && fail == 0) {
        std::cout << "Success!" << std::endl;
    } else if (success > 0 && fail > 0) {
        std::cout << "Error: Mismatched brackets." << std::endl;
        return 1;
    } else if (success > 0) {
        std::cout << "Error: Missing brackets." << std::endl;
        return 1;
    } else if (fail > 0) {
        std::cout << "Error: Mismatched brackets." << std::endl;
        return 1;
    }

    return 0;
}

std::vector<std::string> split(const std::string& code, const std::string& delimiter) {
    std::vector<std::string> tokens;
    std::string currentToken;
    int start = 0;
    for (int i = 0; i < code.size(); i++) {
        if (code[i] == delimiter[0]) {
            currentToken += code[start:i];
            tokens.push_back(currentToken);
            start = i + 1;
        }
    }
    currentToken += code[start:code.size()];
    tokens.push_back(currentToken);
    return tokens;
}
