Here is an example of a Rust function that performs a SHA-256 hash:
```
use std::hash::{Digest, Hash};

fn sha256(data: &[u8]) -> Result<String, std::io::Error> {
  let mut sha256 = Digest::new(Hash::sha256());

  for chunk in data.chunks(8) {
    sha256.write_all(&chunk);
  }

  let mut result = String::new();
  sha256.write_all(&result)
    .map_err(|e| std::io::Error::new(std::io::ErrorKind::Other, e.description()))?;

  Ok(result.trim())
}
```
