```cpp
#include <iostream>
#include <queue>

using namespace std;

void reverse_queue(queue<int>& q) {
    int n = q.size();
    if (n < 2) {
        return;
    }

    // Keep track of the last element in the queue
    int last_element = n - 1;

    // Reverse the queue using a pointer
    queue<int> reverse_queue_ptr;
    reverse_queue_ptr.push(q.front());
    q.pop();
    for (int i = 0; i < n - 1; i++) {
        reverse_queue_ptr.push(q.front());
        q.pop();
    }
    reverse_queue_ptr.push(last_element);

    // Swap the elements from the original queue with the reversed queue
    queue<int> temp;
    temp = q;
    q = reverse_queue_ptr;
    reverse_queue_ptr = temp;

    // Print the reversed queue
    cout << "Reversed queue: ";
    for (int i = 0; i < n; i++) {
        cout << reverse_queue_ptr.front() << " ";
        reverse_queue_ptr.pop();
    }
    cout << endl;
}

int main() {
    queue<int> q;
    q.push(1);
    q.push(2);
    q.push(3);
    q.push(4);
    q.push(5);
    reverse_queue(q);
    return 0;
}
```
