void spSolve(MatrixPtr Matrix,  // pointer to the input matrix
             RealVector RHS,  // pointer to the right-hand side vector
             RealVector Solution, // pointer to the solution vector
             RealVector iRHS,   // pointer to the ith component of the right-hand side vector
             RealVector iSolution) // pointer to the ith component of the solution vector
{
    // check that the input matrix is valid and factored
    assert( IS_VALID(Matrix) && IS_FACTORED(Matrix) );

    if (Matrix->Complex)
    {
        // solve a complex matrix using the SolveComplexMatrix function
        SolveComplexMatrix( Matrix, RHS, Solution, iRHS, iSolution );
        return;
    }

    // initialize the intermediate vector and NAME_1 of the matrix
    RealVector Intermediate = Matrix->Intermediate;
    int NAME_1 = Matrix->NAME_1;

    // get pointers to the row and column indices of the matrix
    int *pExtOrder = &Matrix->IntToExtRowMap[NAME_1];
    int I;

    // copy the right-hand side vector into the intermediate vector
    for (I = NAME_1; I > 0; I--)
        Intermediate[I] = RHS[*(pExtOrder--)];

    // solve the linear system using Gaussian elimination
    for (I = 1; I <= NAME_1; I++)
    {
        // check if the current element is nonzero
        if ((Temp = Intermediate[I]) != 0.0)
        {
            // find the pivot row and column
            ElementPtr pPivot = Matrix->Diag[I];

            // eliminate the current element from the intermediate vector
            Intermediate[I] = (Temp *= pPivot->Real);

            // eliminate the current element from the other rows
            pElement = pPivot->NextInCol;
            while (pElement != NULL)
            {
                Intermediate[pElement->Row] -= Temp * pElement->Real;
                pElement = pElement->NextInCol;
            }
        }
    }

    // backsubstitute to solve for the solution vector
    for (I = NAME_1; I > 0; I--)
    {
        // calculate the current element of the solution vector
        Temp = Intermediate[I];

        // eliminate the current element from the other rows
        pElement = Matrix->Diag[I]->NextInRow;
        while (pElement != NULL)
        {
            Temp -= pElement->Real * Intermediate[pElement->Col];
            pElement = pElement->NextInRow;
        }

        // store the current element of the solution vector
        Solution[*(pExtOrder--)] = Temp;
    }

    // copy the solution vector back to the original vector
    pExtOrder = &Matrix->IntToExtColMap[NAME_1];
    for (I = NAME_1; I > 0; I--)
        Solution[*(pExtOrder--)] = Intermediate[I];
}
