Here is a sample Unity 3D code that creates 100 3D cubes in random locations and rotates them randomly:
```C#
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class RandomCubeGenerator : MonoBehaviour
{
    public GameObject cubePrefab;
    public int numberOfCubes;
    public float minDistance;
    public float maxDistance;
    public float minRotation;
    public float maxRotation;

    private List<GameObject> cubes = new List<GameObject>();

    void Start()
    {
        GenerateCubes();
    }

    void GenerateCubes()
    {
        for (int i = 0; i < numberOfCubes; i++)
        {
            // Create a new cube
            GameObject cube = Instantiate(cubePrefab, Vector3.random, Quaternion.identity);
            cubes.Add(cube);

            // Set the cube's position within the min and NAME_2 distances
            cube.transform.position = Vector3.Lerp(minDistance, maxDistance, Random.Range(0f, 1f));

            // Set the cube's rotation within the min and NAME_2 rotations
            cube.transform.rotation = Quaternion.Lerp(minRotation, maxRotation, Random.Range(0f, 1f));
        }
    }

    void OnDestroy()
    {
        foreach (GameObject cube in cubes)
        {
            Destroy(cube);
        }
    }
}
```
This code uses the `Instantiate` method to create 3D cube prefabs in random locations within the specified min and NAME_2 distances. The `Lerp` method is used to set the cube's rotation within the min and NAME_2 rotations. The `OnDestroy` method is used to destroy all of the generated cubes when the script is destroyed.

