function parseNewsText(text) {
  const lines = text.split('\n');
  const result = [];

  for (const line of lines) {
    const lineSplit = line.split('<br>');

    for (const item of lineSplit) {
      const titleEndIndex = item.indexOf('<');
      const title = item.substring(0, titleEndIndex).trim();
      const rest = item.substring(titleEndIndex);

      const dateOrHourMatches = rest.match(/\d{2}:\d{2}(?:\s*|\b)[AP]M/);
      const dateMatches = rest.match(/\b\d{1,2}\.\s*[A-Za-z]+\s*\d{4}/);

      if (dateOrHourMatches) {
        const hourOrDate = dateOrHourMatches[0].trim();
        const titleWithoutDate = title.replace(hourOrDate, '');
        result.push({
          title: titleWithoutDate,
          hour_or_date: hourOrDate,
        });
      } else if (dateMatches) {
        const date = dateMatches[0].trim();
        const titleWithoutDate = title.replace(date, '');
        result.push({
          title: titleWithoutDate,
          hour_or_date: date,
        });
      } else {
        result.push({
          title: title,
          hour_or_date: '',
        });
      }
    }
  }

  return result;
}

