```javascript
class LocalStorage {
  constructor() {
    this.localStorage = window.localStorage;
  }

  getItem(key) {
    return this.localStorage.getItem(key);
  }

  setItem(key, value) {
    return this.localStorage.setItem(key, value);
  }

  removeItem(key) {
    return this.localStorage.removeItem(key);
  }

  clear() {
    return this.localStorage.clear();
  }

  getItemData(key) {
    let item = this.localStorage.getItem(key);
    if (item === "" || item === null) {
      return undefined;
    }
    let data = item.split(":");
    if (data[0] === "true") {
      return true;
    } else if (data[1] === "false") {
      return false;
    } else if (data[1] === "number") {
      return parseFloat(data[2]);
    } else if (data[1] === "string") {
      return data[2];
    }
  }

  setItemData(key, value) {
    this.localStorage.setItem(key, value + ":");
  }

  removeItemData(key) {
    this.localStorage.removeItem(key);
  }

  save() {
    this.localStorage.sync();
  }
}

```

