```csharp
pragma solidity ^0.8.0;

contract NFT {
    // Define the token's name and symbol
    string public name = "MyNFT";
    string public symbol = "MNFT";

    // Define the token's total supply
    uint public totalSupply;

    // Define the token's owner
    address public owner;

    // Event to signal that an NFT has been sold
    event Sold(address indexed buyer, uint256 index);

    // Constructor to set the owner and total supply
    constructor() public {
        owner = msg.sender;
        totalSupply = 1000000; // 1000000 NFTs
    }

    // Function to allow individuals to buy an NFT
    function buy(uint256 _index) public payable {
        // Check if the NFT is available for sale
        require(totalSupply > _index, "NFT not available for sale");
        // Transfer the NFT to the buyer
        owner.transfer(_index);
        // Remove the NFT from the owner's balance
        totalSupply -= _index;
        // Emit a Sold event to log the transaction
        emit Sold(msg.sender, _index);
    }
}
```
