function sortArray(arr) {
  // sort by priority in descending order
  arr.sort((a, b) => (a.priority > b.priority ? 1 : -1) + (a.created_at > b.created_at ? 1 : -1));

  // sort by created_at in descending order
  arr = arr.sort((a, b) => (a.created_at > b.created_at ? 1 : -1));

  // reverse the array so that the highest priority item is at index 0
  arr = arr.reverse();

  return arr;
}
